/** Workshop stats and their enhancements. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { heading, infobox, sampleLevels, sections, table } from '../render.mjs'

const SAMPLED_NOTE = (count, exportName) =>
  `This track has ${count} levels, so the table shows every level up to 100 and every 100th after that. \`${exportName}\` holds all of them.`

/** `WSP_REND_ARMOR` to `Rend Armor`. */
function enhancementTitle(key) {
  return key
    .replace(/^WSP_/, '')
    .toLowerCase()
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')
}

export function build(context) {
  const { data } = context.sdk
  const { format } = context
  const stats = Object.entries(data.WORKSHOP_DATA)

  for (const [stat, levels] of stats) {
    const keys = Object.keys(levels).map(Number).sort((a, b) => a - b)
    const { indexes, sampled } = sampleLevels(keys.length)
    const rows = indexes.map(index => {
      const level = keys[index]
      const row = levels[level]
      return [level, format.value(row.value), format.cost(row.cash), format.cost(row.coins)]
    })
    context.page(
      `Workshop: ${stat}`,
      sections(
        infobox([
          ['Levels', keys.length],
          ['Value at level 0', format.value(levels[keys[0]].value)],
          [`Value at level ${keys.at(-1)}`, format.value(levels[keys.at(-1)].value)],
        ]),
        heading(2, 'Levels'),
        sampled ? SAMPLED_NOTE(keys.length, 'WORKSHOP_DATA') : '',
        table(['Level', 'Value', 'Cash cost', 'Coin cost'], rows),
        `Back to ${context.link('Workshop')}.`,
      ),
      { source: 'WORKSHOP_DATA' },
    )
  }

  context.page(
    'Workshop',
    sections(
      context.overview('workshop'),
      heading(2, 'Stats'),
      table(
        ['Stat', 'Levels', 'First value', 'Last value'],
        stats.map(([stat, levels]) => {
          const keys = Object.keys(levels).map(Number).sort((a, b) => a - b)
          return [
            context.link(`Workshop: ${stat}`, stat),
            keys.length,
            format.value(levels[keys[0]].value),
            format.value(levels[keys.at(-1)].value),
          ]
        }),
      ),
      `See also ${context.link('Workshop Enhancements')}.`,
    ),
    { source: 'WORKSHOP_DATA' },
  )

  const enhancements = Object.entries(data.WSP_WORKSHOP_COSTS)
  context.page(
    'Workshop Enhancements',
    sections(
      'Coin cost of each workshop enhancement, by level.',
      ...enhancements.map(([key, costs]) => {
        const keys = Object.keys(costs).map(Number).sort((a, b) => a - b)
        const { indexes, sampled } = sampleLevels(keys.length)
        return sections(
          heading(2, enhancementTitle(key)),
          sampled ? SAMPLED_NOTE(keys.length, 'WSP_WORKSHOP_COSTS') : '',
          table(['Level', 'Coin cost'], indexes.map(index => [keys[index], format.cost(costs[keys[index]])])),
        )
      }),
      `Back to ${context.link('Workshop')}.`,
    ),
    { source: 'WSP_WORKSHOP_COSTS' },
  )

  context.group('Workshop', ['Workshop', 'Workshop Enhancements'])
}
